export interface MadarsaIconProps {
  width?: number;
  height?: number;
  size?: number;
}

export const MadarsaIcon: React.FC<MadarsaIconProps> = ({
  width,
  height,
  size = 70,
}) => {
  // madarsa.svg natural size: 128×108 → aspect ratio 128/108
  const h = height ?? size;
  const w = width ?? h * (81 / 67);
  return <SvgXml xml={madarsaSvg} width={w} height={h} />;
};


