// ── Category to Icon Resolver ──────────────────────────────────────────
export interface AnnouncementCategoryIconProps {
  id?: string;
  title?: string;
  size?: number;
  width?: number;
  height?: number;
  color?: string;
  wrapperStyle?: StyleProp<ViewStyle>;
}

export const AnnouncementCategoryIcon: React.FC<AnnouncementCategoryIconProps> = ({
  id = '',
  title = '',
  size = 36,
  width,
  height,
  color,
  wrapperStyle,
}) => {
  const lowerId = (id || '').toLowerCase();
  const lowerTitle = (title || '').toLowerCase();

  let iconNode: React.ReactNode = null;

  if (
    lowerId.includes('fund') ||
    lowerTitle.includes('fund') ||
    lowerTitle.includes('فنڈنگ') ||
    lowerId === '0b2513cc-4aec-4466-a218-fe6a3113796a'
  ) {
    iconNode = <FundingIcon width={width} height={height} size={size} color={color} />;
  } else if (
    lowerId.includes('construction') ||
    lowerTitle.includes('construction') ||
    lowerTitle.includes('تعمیر') ||
    lowerId === '46795502-340e-49ab-8f3c-8c14653362bc'
  ) {
    iconNode = <ConstructionIcon width={width} height={height} size={size} color={color} />;
  } else if (
    lowerId.includes('taqreer') ||
    lowerTitle.includes('taqreer') ||
    lowerTitle.includes('تقریر') ||
    lowerId === '4800d5f2-b9b8-4a3a-98d5-b8a4560e631a'
  ) {
    iconNode = <TaqreerIcon width={width} height={height} size={size} color={color} />;
  } else if (
    lowerId.includes('khutbah') ||
    lowerTitle.includes('khutbah') ||
    lowerTitle.includes('خطبہ') ||
    lowerId === '7b0f22aa-8522-48ed-b72e-5106e0dd7cea'
  ) {
    iconNode = <KhutbahIcon width={width} height={height} size={size} color={color} />;
  } else if (
    lowerId.includes('daily') ||
    lowerTitle.includes('daily') ||
    lowerTitle.includes('روزانہ') ||
    lowerId === '9271b8de-2ce4-4e0b-bd24-3189fbfa3c4e'
  ) {
    iconNode = <DailyProgramsIcon width={width} height={height} size={size} color={color} />;
  } else if (
    lowerId.includes('mega') ||
    lowerTitle.includes('mega') ||
    lowerTitle.includes('بڑے') ||
    lowerId === 'df81963d-ec21-4ea5-8cc0-d2dffec6df3c'
  ) {
    iconNode = <MegaProgramsIcon width={width} height={height} size={size} color={color} />;
  } else if (
    lowerId.includes('janaz') ||
    lowerTitle.includes('janaz') ||
    lowerTitle.includes('جنازہ') ||
    lowerId === 'ea08f71b-3fdd-46eb-91eb-5ebdc183aa59'
  ) {
    iconNode = <JanazaIcon width={width} height={height} size={size} color={color} />;
  } else if (
    lowerId.includes('madarsa') ||
    lowerTitle.includes('madarsa') ||
    lowerTitle.includes('مدرسہ') ||
    lowerId === 'ee65eb1f-037e-464c-a196-4e7bdc008e76'
  ) {
    iconNode = <MadarsaIcon width={width} height={height} size={size} />;
  }

  if (!iconNode) {
    return null;
  }

  if (wrapperStyle) {
    return <View style={wrapperStyle}>{iconNode}</View>;
  }

  return <>{iconNode}</>;
};

// Aliases for convenience
export const MasjidConstructionIcon = ConstructionIcon;
export const DailyIcon = DailyProgramsIcon;
export const FundingProgramsIcon = FundingIcon;
export const JanazhaIcon = JanazaIcon;
export const JummahKhutbahIcon = KhutbahIcon;
export const MadarsaUpdatesIcon = MadarsaIcon;
export const MegaIcon = MegaProgramsIcon;


